import json, urllib.request

token = json.loads(open('/tmp/owner_at.json').read())['accessToken']
url = 'https://api.ivxholding.com/api/ivx/developer-deploy/action'
headers = {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}

print("=" * 70)
print("PHASE 2 — EXECUTE DB CONSTRAINTS MIGRATION (adjusted for real schema)")
print("=" * 70)

# Adjusted migration based on actual schema inspection:
# - profiles.id IS already PK (auth user id) — no separate auth_user_id column
# - members.auth_user_id exists (text, nullable) — add unique index
# - members has NO normalized_email — create + backfill + unique index
# - landing_investments has NO registration_request_id — create + unique index
# - investment_interest table may not exist — check + add FK if it does
sql = """
-- ============================================================================
-- IVX Registration DB Constraints Migration (adjusted for actual schema)
-- ============================================================================

-- 1. members.auth_user_id UNIQUE
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public' AND tablename = 'members' AND indexname = 'idx_members_auth_user_id_unique'
  ) THEN
    CREATE UNIQUE INDEX idx_members_auth_user_id_unique ON public.members (auth_user_id)
    WHERE auth_user_id IS NOT NULL;
  END IF;
END $$;

-- 2. members.normalized_email — create column + backfill + unique index
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'members' AND column_name = 'normalized_email'
  ) THEN
    ALTER TABLE public.members ADD COLUMN normalized_email text;
    UPDATE public.members SET normalized_email = lower(trim(email)) WHERE email IS NOT NULL;
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public' AND tablename = 'members' AND indexname = 'idx_members_normalized_email_unique'
  ) THEN
    CREATE UNIQUE INDEX idx_members_normalized_email_unique ON public.members (normalized_email)
    WHERE normalized_email IS NOT NULL;
  END IF;
END $$;

-- 3. landing_investments.registration_request_id — create column + unique index
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'landing_investments' AND column_name = 'registration_request_id'
  ) THEN
    ALTER TABLE public.landing_investments ADD COLUMN registration_request_id text;
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public' AND tablename = 'landing_investments' AND indexname = 'idx_landing_investments_reg_req_id_unique'
  ) THEN
    CREATE UNIQUE INDEX idx_landing_investments_reg_req_id_unique ON public.landing_investments (registration_request_id)
    WHERE registration_request_id IS NOT NULL;
  END IF;
END $$;

-- 4. profiles.id is already PK = auth.users.id — no separate auth_user_id column needed
--    But add FK from profiles.id → auth.users.id if not already present
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.table_constraints
    WHERE table_schema = 'public' AND table_name = 'profiles' AND constraint_name = 'fk_profiles_auth_user_id'
  ) THEN
    ALTER TABLE public.profiles
      ADD CONSTRAINT fk_profiles_auth_user_id
      FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'profiles FK not added: %', SQLERRM;
END $$;

-- 5. members.auth_user_id → auth.users.id FK
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.table_constraints
    WHERE table_schema = 'public' AND table_name = 'members' AND constraint_name = 'fk_members_auth_user_id'
  ) THEN
    ALTER TABLE public.members
      ADD CONSTRAINT fk_members_auth_user_id
      FOREIGN KEY (auth_user_id) REFERENCES auth.users(id) ON DELETE SET NULL;
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'members FK not added: %', SQLERRM;
END $$;
"""
payload = json.dumps({
    'action': 'supabase_execute_sql_management',
    'input': {'sql': sql},
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_SUPABASE_MIGRATION'
}).encode('utf-8')
req = urllib.request.Request(url, data=payload, headers=headers, method='POST')
try:
    with urllib.request.urlopen(req, timeout=60) as resp:
        data = json.loads(resp.read().decode('utf-8'))
        r = data.get('result', {})
        print(f"ok: {r.get('ok')}")
        print(f"httpStatus: {r.get('httpStatus')}")
        if r.get('ok'):
            rows = r.get('rows', [])
            print(f"Rows: {len(rows) if isinstance(rows, list) else 'N/A'}")
            if isinstance(rows, list):
                for row in rows[:10]:
                    print(f"  {row}")
            else:
                print(f"  Raw: {str(rows)[:300]}")
        else:
            print(f"error: {str(r.get('error', 'N/A'))[:500]}")
except urllib.error.HTTPError as e:
    print(f'HTTP {e.code}: {e.read().decode("utf-8")[:500]}')
PYEOF

